/// <summary>
/// PaffH 19.08.25
/// </summary>
[ExtensionOf(formstr(AVAKBVBuildingProjectSearch))]
public final class NDXAVAKBVBuildingProjectSearch_frm_Extension
{
    public NDXBVSearchContract bvSearchContract;
    public NDXBVEMailRequestControlCenterFormI nDXBVEMailRequestControlCenterFormI;


}

Method.Source:
/// <summary>
/// PaffH 19.08.25
/// last modified: PaffH 09.10.25
/// </summary>
public void init()
{
    // get contract
    Args args = this.args();
    if (args && args.caller() is NDXFormHandlerIncludedI)
    {
        NDXFormHandlerIncludedI nDXFormHandlerIncludedI = args.caller() as NDXFormHandlerIncludedI;
        if (nDXFormHandlerIncludedI)
        {
            if (nDXFormHandlerIncludedI.parmFormhandler() is NDXBVEMailRequestControlCenterForm)
            {
                NDXBVEMailRequestControlCenterForm formHandler = nDXFormHandlerIncludedI.parmFormhandler();
                if (formHandler is NDXBVEMailRequestControlCenterFormI)
                {
                    isCalledFromBVEmailRequestControlCenter = true;
                    nDXBVEMailRequestControlCenterFormI = formHandler as NDXBVEMailRequestControlCenterFormI;
                    bvSearchContract = nDXBVEMailRequestControlCenterFormI.fillContract();
                }
            }
        }
    }

    next init();

    if (bvSearchContract)
    {
        this.design().controlName(formControlStr(AVAKBVBuildingProjectSearch, NDXAssignBVToEmailRequest)).enabled(bvSearchContract.parmInEditMode());
    }

    // activate tab BV E-Mail board            
    FormActionPaneTabControl ctrl = this.design().controlName(formControlStr(AVAKBVBuildingProjectSearch, NDXFormActionPaneTabBVEmailBoard));
    ctrl.visible(isCalledFromBVEmailRequestControlCenter);
}

/// <summary>
/// PaffH 03.09.25
/// </summary>
/// <returns>bvSearchContract</returns>
public NDXBVSearchContract getNDXBVSearchContract()
{
    return bvSearchContract;
}

/// <summary>
/// PaffH 06.10.25
/// </summary>
/// <returns>NDXBVEMailRequestControlCenterFormI</returns>
public NDXBVEMailRequestControlCenterFormI getNDXBVEMailRequestControlCenterFormI()
{
    return nDXBVEMailRequestControlCenterFormI;
}

/// <summary>
/// PaffH 19.08.25
/// </summary>
/// <param name = "_contract">NDXBVSearchContract</param>
public void fillFormValuesFromContract(NDXBVSearchContract _contract)
{
    if (_contract.parmBuildingProjectId())
    {
        this.editBuildingProjectId(true, _contract.parmBuildingProjectId());
        this.editOperatorBuildingProjectId(true, AVASqlOperator::Like);
    }
    if (_contract.parmCity())
    {
        this.editCity(true, _contract.parmCity());
        this.editOperatorCity(true, _contract.parmOperatorCity());
    }
    if (_contract.parmSubject())
    {
        this.editSubject(true, _contract.parmSubject());
        this.editOperatorSubject(true, _contract.parmOperatorSubject());
    }
    if (_contract.parmContactName())
    {
        this.editContactName(true, _contract.parmContactName());
        this.editOperatorContact(true, _contract.parmOperatorContact());
    }
    if (_contract.parmPartyName())
    {
        this.editPartyName(true, _contract.parmPartyName());
        this.editOperatorParty(true, AVASqlOperator::Like);
    }
}
